const claimTypeFor=(claim:LegacyClaimVerification):ClaimType=>claim.cannotProve.toLowerCase().includes('causal')?'causal':claim.assessment==='uncertain'?'predictive':'mixed';
const evidenceStrengthFor=(claim:LegacyClaimVerification):EvidenceStrength=>claim.assessment==='uncertain'||claim.assessment==='unsupported'?'limited':'medium';
const crossTopicSlugs:Record<string,string[]>= {
  'inmigracion-delincuencia':['inmigracion','seguridad'], 'inmigrantes-pensiones':['inmigracion','juventud','economia'],
  'demasiados-graduados':['empleo','juventud'], 'espana-impuestos-europa':['impuestos','economia'], 'espana-pobreza-cuarta-parte':['desigualdad','juventud'],
};
export const claims:ClaimVerification[]=[...legacyClaims,...additionalClaims,...eventClaims].map((claim)=>{ const md=markdownClaims.find((record)=>record.slug===claim.slug); return ({
  ...claim,
  claim:md?.claim || claim.claim,
  assessment:(md?.assessment as ClaimAssessment) || claim.assessment,
  whatIsTrue:md?.whatIsTrue || claim.whatIsTrue,
  whatIsMissing:md?.whatIsMissing || claim.whatIsMissing,
  scale:md?.scale || claim.scale,
  cannotProve:md?.cannotProve || claim.cannotProve,
  shareable:md?.shareable || claim.shareable,
  topicSlugs:crossTopicSlugs[claim.slug] || (md?.topicSlugs?.length ? md.topicSlugs : [claim.topicSlug]),
  aliases:md?.aliases?.length ? md.aliases : claim.keywords,
  claimType:md?.claimType || claimTypeFor(claim),
  evidenceStrength:md?.evidenceStrength || evidenceStrengthFor(claim),
  decisiveEvidence:claim.scale,
  competingExplanations:[],
  whyItCirculates:'La afirmación combina una experiencia visible, una formulación política o una simplificación de una estadística.',
  unknowns:claim.cannotProve,
  evidenceCouldChange:'Una nueva fuente primaria comparable, una revisión metodológica o un cambio relevante en el periodo analizado.',
  propositionIds:md?.propositionIds || [], relatedSlugs:md?.relatedSlugs || [], supports:md?.supports || [], contradicts:md?.contradicts || [], dependsOn:md?.dependsOn || [], geography:md?.geography || 'España', period:md?.period || '2025-2026', published:md?.status === 'published',
  reviewed:md?.reviewed || '2026-07-12', sourceRefs:md?.sourceRefs || [], contextMode:md?.contextMode || 'topic', visualType:md?.visualType || '', visualOrigin:md?.visualOrigin || '', visualDestination:md?.visualDestination || '', visualAmount:md?.visualAmount || '', visualComparisonLabels:md?.visualComparisonLabels || [], visualComparisonValues:md?.visualComparisonValues || [], visualComparisonUnit:md?.visualComparisonUnit || '',
  evidenceIds:md?.evidenceIds?.length ? md.evidenceIds : claim.sources.map(evidenceId),
}); });
for(const claim of claims){
  claim.relatedSlugs=claims.filter((other)=>other.slug!==claim.slug&&other.published&&(other.topicSlugs.some((slug)=>claim.topicSlugs.includes(slug))||other.keywords.some((keyword)=>claim.keywords.includes(keyword)))).slice(0,6).map((other)=>other.slug);
}
const validClaimTypes=new Set<ClaimType>(['descriptive','comparative','definition','trend','causal','predictive','legal','normative','mixed']);
const validEvidenceStrengths=new Set<EvidenceStrength>(['high','medium','limited','insufficient']);
const claimFailures=claims.flatMap((claim)=>[
  !claim.slug||!claim.claim?`${claim.slug||'unknown'}: missing identity`:null,
  !claim.topicSlugs.length?`${claim.slug}: missing topic`:null,
  !validClaimTypes.has(claim.claimType)?`${claim.slug}: invalid claim type`:null,
  !validEvidenceStrengths.has(claim.evidenceStrength)?`${claim.slug}: invalid evidence strength`:null,
  !claim.reviewed?`${claim.slug}: missing review date`:null,
  !claim.sources.length?`${claim.slug}: missing sources`:null,
].filter((failure):failure is string=>Boolean(failure)));
if(claimFailures.length)throw new Error(`Invalid claim catalogue:\n${claimFailures.join('\n')}`);
export const assessmentLabels:Record<ClaimAssessment,string>={'true':'Verdadero','mostly-true':'Mayormente cierto','misleading':'Generalización engañosa','unsupported':'Sin respaldo suficiente','uncertain':'Incierto','false':'Falso'};
export const getClaim=(slug:string)=>claims.find(item=>item.slug===slug);
